package io.github.polestarcn.companion;
import android.content.*;import org.json.*;import java.util.*;import java.io.*;import java.util.concurrent.*;
/** Only allowlisted UI/configuration preferences; no accounts, tokens, VINs or runtime sessions. */
final class SettingsBackup {
 static final ExecutorService WORK=Executors.newSingleThreadExecutor();
 private static final Set<String> KEYS=new HashSet<>(Arrays.asList("all_good_lines","all_good_position","all_good_shimmer","all_good_weight","app_background_enabled","app_icon_mode","app_icon_style","background_image_enabled","battery_capacity_kwh","behind","bottom","button_background_percent","charging_animation","climate_custom_target","climate_target_c","condition_display","condition_service_distance","control_action_auth_","effect_enabled","energy_months","energy_price","experimental_tire","feedback_","feedback_bold","feedback_sp","focus_x","focus_y","fx_air","fx_air_direction","fx_air_shape","fx_air_speed","fx_air_tint","fx_arc_percent","fx_charge","fx_charge_speed","fx_direction","fx_fade","fx_heating","fx_lines","fx_particle_size","fx_particles","fx_purification","fx_strength","fx_style","fx_trail_length","fx_turbulence","fx_turbulence_percent","fx_window_glow","fx_window_period","fx_window_range","fx_window_strength","haptic_strength","haptics","hero_number_weight","home_metrics","immersive","language","left","light_effects","map_backdrop","map_backdrop_blur","map_backdrop_provider","map_backdrop_spread","map_backdrop_zoom","page_transition","phone_location_refresh","pseu_type","range","refresh_on_open","refresh_only_charging","refresh_wifi_only","resident","right","show_battery_bar","show_button_feedback","show_car","show_charging","show_tire_status","show_update","skin_order","theme","top","trunk_icon","ui_button_bold","ui_data_bold","ui_skin","vehicle_art_day","vehicle_art_night","volike_detail","volike_simple_labels","watch_skin","widget_bold","widget_design","widget_font_percent","widget_frost","widget_ink","widget_ink_custom","widget_language","widget_opacity","widget_style","widget_visual","map_theme","map_pin_size_percent","map_pin_color","map_pin_focus_x","map_pin_focus_y","effect_auto_scenes","fx_window_feather","notification_icon_style","notification_status_icon","camp_interval","camp_minimum","vehicle_art_model_day","vehicle_art_model_night","ui_all_bold","charging_sweep_style","charging_sweep_period","charging_sweep_strength","charging_sweep_color","foreground_refresh_minutes","app_background_minutes","widget_refresh_minutes","map_refresh_minutes"));
 static boolean allowed(String key){if(key.equals("phone_location_refresh")||key.equals("resident"))return false;return KEYS.contains(key)||key.matches("condition_(good_text|problem_text|line_spacing|focus_x|focus_y|stretch|size|color|check_size)")||key.matches("fx_(charge|climate|clean)_field_(range|top|bottom|left|right|behind|focus_x|focus_y)")||key.matches("font_percent_(simple|detailed|volike_polestar|niolike|niolike2|ps_default|simple2)")||key.matches("feedback_(lock|trunk|climate|air|windows|signal|camp)")||key.matches("(pseu_)?widget_(buttons_[A-Z_]+|metrics_[a-zA-Z0-9_]+)")||key.matches("control_action_auth_[a-z-]+")||key.matches("(app|widget|foreground|map)_.*minutes");}
 static JSONObject export(Context c)throws JSONException{JSONObject values=new JSONObject();for(Map.Entry<String,?> e:c.getSharedPreferences("preferences",0).getAll().entrySet())if(allowed(e.getKey())&&e.getValue() instanceof String)values.put(e.getKey(),e.getValue());return new JSONObject().put("format","PsaSettings").put("schema",1).put("version",BuildConfig.VERSION_NAME).put("values",values);}
 static JSONObject read(InputStream in)throws Exception{if(in==null)throw new IOException("Missing file");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[4096];for(int n;(n=in.read(buffer))!=-1;){if(out.size()+n>262144)throw new IOException("Backup too large");out.write(buffer,0,n);}JSONObject root=new JSONObject(out.toString("UTF-8"));if(!"PsaSettings".equals(root.optString("format"))||root.optInt("schema")!=1)throw new IOException("Unsupported backup");JSONObject values=root.getJSONObject("values");if(values.length()>600)throw new IOException("Too many settings");Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();Object value=values.get(key);if(!allowed(key)||!(value instanceof String)||((String)value).length()>4096)throw new IOException("Unsupported setting");}return values;}
 static void restore(Context c,JSONObject values)throws JSONException{SharedPreferences.Editor e=c.getSharedPreferences("preferences",0).edit();Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next();if(!allowed(key))throw new JSONException("Unsupported setting");e.putString(key,values.getString(key));}e.apply();}
 static void reset(Context c){SharedPreferences p=c.getSharedPreferences("preferences",0);SharedPreferences.Editor e=p.edit();for(String key:p.getAll().keySet())if(allowed(key)||key.equals("resident")||key.startsWith("expand_"))e.remove(key);e.apply();}
 private SettingsBackup(){}
}
